 function hit(e){const r=canvas.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)return -1;pointer.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);camera.updateMatrixWorld();scene.updateMatrixWorld(true);ray.setFromCamera(pointer,camera);return ray.intersectObjects(slots.map(s=>s.surface),false)[0]?.object.userData.slot??-1;}

 let thumbRenderer;
 function preferredSlot(){camera.updateMatrixWorld();let best=0,score=Infinity;slots.forEach((s,i)=>{const p=new T.Vector3().fromBufferAttribute(s.surface.geometry.attributes.position,0).project(camera),cost=Math.abs(p.x)+Math.abs(p.y)*1.3+(p.z>1?100:0);if(cost<score){best=i;score=cost;}});return best;}
 function framePreview(group){const box=new T.Box3().setFromObject(group);if(box.isEmpty())return;const {tiles,diameter,heightAt}=getBoard();for(const t of tiles)for(let i=0;i<6;i++){const a=i*Math.PI/3,x=t.center.x+Math.sin(a)*diameter/2,z=t.center.z+Math.cos(a)*diameter/2;box.expandByPoint(new T.Vector3(x*.1,heightAt(x,z)*.1,z*.1));}const center=box.getCenter(new T.Vector3()),radius=box.getSize(new T.Vector3()).length()/2,direction=camera.position.clone().sub(orbit.target).normalize(),angle=Math.min(camera.fov*Math.PI/360,Math.atan(Math.tan(camera.fov*Math.PI/360)*camera.aspect)),distance=Math.min(orbit.maxDistance,Math.max(camera.position.distanceTo(orbit.target),radius/Math.sin(angle)*1.12));orbit.target.copy(center);camera.position.copy(center).addScaledVector(direction,distance);orbit.update();}
 function thumbnail(group,id){try{thumbRenderer??=new T.WebGLRenderer({alpha:true,antialias:true});thumbRenderer.setSize(180,100);thumbRenderer.setPixelRatio(1);thumbRenderer.toneMapping=T.ACESFilmicToneMapping;const stage=new T.Scene(),copy=group.clone(true),bounds=new T.Box3().setFromObject(copy),center=bounds.getCenter(new T.Vector3()),size=bounds.getSize(new T.Vector3()),camera=new T.PerspectiveCamera(35,1.8,.01,2000);stage.add(copy,new T.HemisphereLight('#fff6dc','#85806b',2.4));const sun=new T.DirectionalLight('#fff3d3',3);sun.position.copy(center).add(new T.Vector3(10,20,10));sun.target.position.copy(center);stage.add(sun,sun.target);camera.position.copy(center).add(new T.Vector3(.7,1,1).normalize().multiplyScalar(size.length()*1.35));camera.lookAt(center);thumbRenderer.render(stage,camera);const card=[...options.children].find(b=>b.dataset.type===id),img=card.querySelector('img');img.src=thumbRenderer.domElement.toDataURL();img.hidden=false;}catch{ /* In-world preview remains available without an auxiliary WebGL context. */ }}
 function select(i){selected=i;highlight(i);if(type){load(type,i);return;}add.hidden=true;status.textContent='Choose a tile to preview here, or drag one onto an empty hex.';}
 function highlight(i){slots.forEach((s,j)=>s.line.material.color.set(j===i?'#b84931':'#798269'));}
 async function load(id,i,place=false){const request=++token;clearAsset();type=id;renderControls();selected=i;loading=true;highlight(i);add.hidden=false;add.disabled=true;status.textContent='Growing preview…';for(const b of options.children)b.setAttribute('aria-pressed',String(b.dataset.type===id));try{const next=await preview(id,i,{...settings()});if(!opened||request!==token){next.dispose();return;}asset=next;scene.add(next.group);framePreview(next.group);thumbnail(next.group,id);canvas.dataset.tilePreview=JSON.stringify({type:id,slot:i,garden:id==='crop'?settings():null,settings:{...settings()},children:next.group.children.length});status.textContent=next.warning||descriptions[id];loading=false;add.disabled=false;if(place)await commit();}catch(e){if(request===token){loading=false;add.disabled=true;status.textContent=e.message;}}}
 async function commit(){if(!asset||loading)return;const apply=asset.commit;try{const placed=asset,placing=apply();asset=null;placed.dispose();close(true);await placing;}catch(e){document.querySelector('#error').textContent=e.message;}}
 for(const [id,label]of TILE_CHOICES){const b=document.createElement('button');const image=document.createElement('img');image.alt='';image.hidden=true;const caption=document.createElement('span');caption.textContent=label;b.setAttribute('aria-label','Drag '+label+' to place');b.append(image,caption);b.dataset.type=id;b.title=descriptions[id];b.onclick=()=>{if(!b.suppressClick){type=id;for(const card of options.children)card.setAttribute('aria-pressed',String(card===b));if(selected>=0)load(id,selected);else status.textContent=descriptions[id]+' Click an empty hex to preview.';}b.suppressClick=false;};b.addEventListener('pointerdown',e=>{if(cameraOwnsPointer(e)||e.altKey)return;drag={id:e.pointerId,type:id,x:e.clientX,y:e.clientY,moved:false,button:b};b.setPointerCapture(e.pointerId);});b.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;if(Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>7)drag.moved=true;if(drag.moved){highlight(hit(e));status.textContent='Drop onto an outlined hex to place.';}});b.addEventListener('pointerup',e=>{if(!drag||drag.id!==e.pointerId)return;const d=drag;drag=null;if(d.moved){b.suppressClick=true;setTimeout(()=>b.suppressClick=false,0);const i=hit(e);if(i>=0&&!cameraOwnsPointer(e)&&!e.altKey)load(id,i,true);else{highlight(selected);status.textContent='Drop cancelled. Choose a tile or try again.';}}});b.addEventListener('pointercancel',()=>{drag=null;highlight(selected);});options.append(b);}
 function open(){if(!allowed())return;openingView={position:camera.position.clone(),target:orbit.target.clone()};panel.prepend(launch);opened=true;selected=-1;type=null;panel.hidden=false;options.hidden=true;add.hidden=true;heading.textContent='Choose an empty hex';status.textContent='Click an outlined hex in the world.';launch.setAttribute('aria-expanded','true');const {tiles,diameter,heightAt}=getBoard();camera.position.sub(orbit.target).multiplyScalar(1.18).clampLength(orbit.minDistance,orbit.maxDistance).add(orbit.target);orbit.update();
  slots=frontier(tiles,diameter).map((cell,index)=>{const center=tileCenter(cell.q,cell.r,diameter),points=[],vertices=[],object=new T.Group();const p=(a)=>{const edge=Math.floor(a/(Math.PI/3)),t=a/(Math.PI/3)-edge,b=edge*Math.PI/3,c=b+Math.PI/3;const x=center.x+(Math.sin(b)*(1-t)+Math.sin(c)*t)*diameter/2,z=center.z+(Math.cos(b)*(1-t)+Math.cos(c)*t)*diameter/2;return new T.Vector3(x*.1,heightAt(x,z)*.1+.045,z*.1);};const middle=new T.Vector3(center.x*.1,heightAt(center.x,center.z)*.1+.045,center.z*.1);for(let e=0;e<48;e++){const a=p(e*Math.PI/24),b=p((e+1)*Math.PI/24);points.push(a);vertices.push(...middle.toArray(),...a.toArray(),...b.toArray());}const surface=new T.Mesh(new T.BufferGeometry().setAttribute('position',new T.Float32BufferAttribute(vertices,3)),new T.MeshBasicMaterial({color:'#e9e2c8',transparent:true,opacity:.18,side:T.DoubleSide,depthWrite:false}));surface.userData.slot=index;const line=new T.LineLoop(new T.BufferGeometry().setFromPoints(points),new T.LineBasicMaterial({color:'#798269',depthTest:false}));line.raycast=()=>{};object.add(surface,line);scene.add(object);return {object,surface,line};});
 }
 launch.onclick=()=>{if(!allowed())return;picker.hidden=!picker.hidden;const rect=launch.getBoundingClientRect();picker.style.left=Math.max(10,Math.min(rect.left,window.innerWidth-210))+'px';picker.style.bottom=Math.max(10,window.innerHeight-rect.top+8)+'px';launch.setAttribute('aria-expanded',String(!picker.hidden));};panel.querySelector('.tile-expand-heading button').onclick=()=>close();add.innerHTML=uiIcon('largeHex').replace('</svg>','<path d="M12 7v10M7 12h10"/></svg>');add.title=add.ariaLabel='Place here';add.onclick=commit;
 // Listen before canvas handlers but leave camera gestures and drags untouched.
 const down=e=>{if(e.pointerType==='touch'){touches.add(e.pointerId);if(touches.size>1){press=null;return;}}if(opened&&!cameraOwnsPointer(e)&&!e.altKey){const i=hit(e);press=i>=0?{id:e.pointerId,x:e.clientX,y:e.clientY,index:i}:null;}};
 const up=e=>{touches.delete(e.pointerId);const p=press;press=null;if(!opened||!p||p.id!==e.pointerId||cameraOwnsPointer(e)||e.altKey||Math.hypot(e.clientX-p.x,e.clientY-p.y)>5||hit(e)!==p.index)return;select(p.index);};
 canvas.addEventListener('pointerdown',down);canvas.addEventListener('pointerup',up);canvas.addEventListener('pointercancel',e=>{touches.delete(e.pointerId);press=null;});window.addEventListener('keydown',e=>{if(e.key==='Escape')close();});
 return {close,get opened(){return opened;},dispose(){close();thumbRenderer?.dispose();thumbRenderer?.forceContextLoss();resize?.disconnect();window.removeEventListener('resize',positionTitle);canvas.removeEventListener('pointerdown',down);canvas.removeEventListener('pointerup',up);panel.remove();launch.remove();picker.remove();sceneType.remove();}};
